@tuple
class modint:
    x: u32

    def __new__():
        return modint(u32(0))

    def __new__(y: int) -> modint:
        z = y % 998244353
        if z < 0:
            z += 998244353
        return modint(u32(z))

    def __add__(self, rhs: modint) -> modint:
        res = self.x + rhs.x
        if res >= u32(998244353):
            res -= u32(998244353)
        return modint(res)

    def __sub__(self, rhs: modint) -> modint:
        res = self.x - rhs.x
        if res >= u32(998244353):
            res += u32(998244353)
        return modint(res)

    def __mul__(self, rhs: modint) -> modint:
        res = u64(self.x) * u64(rhs.x) % u64(998244353)
        return modint(u32(res))

    def __neg__(self) -> modint:
        return modint(u32(0) if self.x == u32(0) else u32(998244353) - self.x)

    def __str__(self) -> str:
        return str(self.x)

def dirichlet_conv(a, b):
    c = [modint(0)] * (U + 1)
    for i in range(1, U + 1):
        for j in range(1, U // i + 1):
            c[i * j] += a[i] * b[j]
    return c

def dirichlet_inv(a):
    assert a[1] == modint(1)
    b = [modint(0)] * (U + 1)
    b[1] = modint(1)
    for i in range(1, U + 1):
        for j in range(2, U // i + 1):
            b[i * j] -= b[i] * a[j]
    return b

